from document_models import NormalizedExpense, LineItem
from typing import Dict, Any

def validate_document_fields(expense: NormalizedExpense, required_fields: list[str]) -> Dict[str, Any]:
    validation_results = {"is_valid": True, "missing_fields": [], "confidence_scores": {}}

    # Basic field presence validation
    for field in required_fields:
        if not getattr(expense, field, None):
            validation_results["is_valid"] = False
            validation_results["missing_fields"].append(field)

    # Mock confidence score check (in a real scenario, Document AI provides confidence scores per entity)
    # For this example, we'll just set a dummy confidence for the presence of total_amount
    if expense.total_amount is not None:
        validation_results["confidence_scores"]["total_amount"] = 0.95 # High confidence if extracted
    else:
        validation_results["confidence_scores"]["total_amount"] = 0.0 # No confidence if not extracted

    # Add more sophisticated confidence checks here based on Document AI's output
    # For line items, you might iterate and check confidence for each line item's fields
    for i, item in enumerate(expense.line_items):
        if item.description:
            validation_results["confidence_scores"][f"line_item_{i}_description"] = 0.90
        if item.total_price:
            validation_results["confidence_scores"][f"line_item_{i}_total_price"] = 0.85


    return validation_results

from document_models import Invoice

def summarize_invoice(invoice: Invoice) -> str:
    summary_parts = []
    summary_parts.append("--- Invoice Summary ---")
    if invoice.vendor_name:
        summary_parts.append(f"Vendor: {invoice.vendor_name}")
    if invoice.invoice_date:
        summary_parts.append(f"Date: {invoice.invoice_date}")
    if invoice.total_amount is not None:
        summary_parts.append(f"Total Amount: ${invoice.total_amount:.2f}")

    if invoice.line_items:
        summary_parts.append("Line Items:")
        for item in invoice.line_items:
            item_summary = f"  - {item.description}"
            if item.quantity is not None:
                item_summary += f" (Qty: {item.quantity})
            if item.unit_price is not None:
                item_summary += f" (Unit Price: ${item.unit_price:.2f})
            if item.total_price is not None:
                item_summary += f" (Total: ${item.total_price:.2f})
            summary_parts.append(item_summary)

    if not summary_parts:
        return "No significant invoice details to summarize."

    return "\n".join(summary_parts)

import os
from google.cloud import translate_v3beta1 as translate

def translate_invoice_notes(text: str, target_language: str = "en") -> dict:
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set.")

    client = translate.TranslationServiceClient()

    location = "global" # Or a specific region if needed
    parent = f"projects/{project_id}/locations/{location}"

    try:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text],
                "target_language_code": target_language,
            }
        )

        translations = []
        for translation in response.translations:
            translations.append(translation.translated_text)

        return {
            "original_text": text,
            "translated_text": translations[0] if translations else "",
            "target_language": target_language,
            "provider": "google_cloud_translation"
        }

    except Exception as e:
        return {
            "original_text": text,
            "translated_text": "",
            "target_language": target_language,
            "error": str(e),
            "provider": "google_cloud_translation"
        }
